import{z as n,x as s,o as e,c as o,q as A,j as r,D as E,d as B,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"市场风险体系","description":"","frontmatter":{"title":"市场风险体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-market-system.md","filePath":"quant/rk-market-system.md","lastUpdated":1791063341000}'),d={name:"quant/rk-market-system.md"};function m(p,a,h,u,D,c){const t=s("Mermaid");return e(),o("div",null,[a[2]||(a[2]=A('<h1 id="市场风险体系" tabindex="-1">市场风险体系 <a class="header-anchor" href="#市场风险体系" aria-label="Permalink to &quot;市场风险体系&quot;">​</a></h1><div class="epigraph"><p>市场风险体系不是一个大模型，而是一条流水线：持仓进来、因子出去、分位数落地，每一环都能单独指认错误。</p><footer>—— 据 Jorion, *Value at Risk*；McNeil, Frey and Embrechts, *Quantitative Risk Management*, 2005 整理</footer></div><p><a href="/quant/cn-compliance-map">上一课</a>把合规红线收束在上一课程末尾：红线按行为模式与监控数据落判，报备与速率监控必须勾稽。合规回答「能不能做」，本课起回答「仓能做多大、亏到哪要停」——本课是「风险体系深化」的第一课。主干已交付计量件：<a href="/quant/var-methods">VaR：历史、参数、MC</a> 的三种算法、<a href="/quant/expected-shortfall">Expected Shortfall</a> 的连贯性、<a href="/quant/liquidity-adjusted-var">流动性调整 VaR</a> 的变现成本、<a href="/quant/regime-break-risk">体制切换失效</a>的失效路径。本课程不重写这些定义，而是把它们组装成机构口径：先计量四类风险——市场、流动性、对手方、操作；再治理六件事——模型、压力、归因、限额、资本、报告。第一课钉住市场风险的流水线框架。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>给单本账簿算一个 \\(99\\%\\) 分位数不难；缺口在于让全机构对同一口径负责。常见断点有三处。其一，头寸映射：交易簿里的奇异结构折不进风险引擎的因子向量，剩下多少基础风险没人记账。其二，双套数字：前台灵敏度与风控全重估各算各的，差值被当成噪声，隐性头寸藏在正负相抵里。其三，例外无闭环：回测穿透后没人改窗口、改模型或降限额，计量退化成日报插画。断在哪一环，错的性质就不同：映射断的是覆盖，重估断的是口径，回测断的是治理——不按环定位，修模型的力气会花在错的地方。</p><p><span class="marginnote">术语翻译：基础风险就是「模型没看见的那部分风险」——风险引擎只认它认识的因子，奇异结构折不进去的剩余暴露就落在这里。像只按身高分区间的衣柜：塞不进去的那件外套不会消失，只会堆在椅子上没人记账。</span></p><h3 id="流水线的六环" tabindex="-1">流水线的六环 <a class="header-anchor" href="#流水线的六环" aria-label="Permalink to &quot;流水线的六环&quot;">​</a></h3><p>体系固定成一张作业图，每环有独立的责任人与失败模式；先立全图，再逐环细写。</p>',8)),(e(),r(l,null,{default:E(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SNAP%5B%22%E6%8C%81%E4%BB%93%E5%BF%AB%E7%85%A7%EF%BC%9A%E5%86%BB%E7%BB%93%E6%97%B6%E7%82%B9%22%5D%20--%3E%20MAP%5B%22%E5%9B%A0%E5%AD%90%E6%98%A0%E5%B0%84%EF%BC%9A%E5%A3%B0%E6%98%8E%E5%9F%BA%E7%A1%80%E9%A3%8E%E9%99%A9%22%5D%0A%20%20MAP%20--%3E%20SCEN%5B%22%E6%83%85%E6%99%AF%EF%BC%9A%E7%AA%97%E5%8F%A3%E4%B8%8E%E6%9D%A1%E4%BB%B6%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20SCEN%20--%3E%20REVAL%5B%22%E9%87%8D%E4%BC%B0%EF%BC%9A%E7%81%B5%E6%95%8F%E5%BA%A6%E6%88%96%E5%85%A8%E9%87%8D%E4%BC%B0%22%5D%0A%20%20REVAL%20--%3E%20DIST%5B%22%E7%BB%84%E5%90%88%E6%8D%9F%E5%A4%B1%E5%88%86%E5%B8%83%22%5D%0A%20%20DIST%20--%3E%20QUANT%5B%22%E5%88%86%E4%BD%8D%E6%95%B0%EF%BC%9AVaR%20%E4%B8%8E%20ES%22%5D%0A%20%20QUANT%20--%3E%20BT%5B%22%E5%9B%9E%E6%B5%8B%E4%BE%8B%E5%A4%96%E4%B8%8E%E9%99%90%E9%A2%9D%E6%8E%A5%E5%8F%A3%22%5D%0A%20%20BT%20--%3E%7C%22%E8%AF%8A%E6%96%AD%E5%8F%8D%E9%A6%88%22%7C%20MAP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>因子映射把每个头寸写成风险因子向量的函数：债券折成关键期限点的现金流，期权簿折成 Delta、Gamma、Vega 加曲面因子；映射放弃的部分就是基础风险，必须有名字、有量级。情景生成二选一：历史法直接搬 \\(N\\) 天的因子联合变动，\\(N\\) 常取 \\(250\\) 到 \\(500\\)；参数法用协方差椭圆，条件波动由 EWMA 或 GARCH 更新，使分位数随今日 \\(\\sigma_t\\) 收紧。重估分级：线性账簿用灵敏度内积就够，期权簿要全重估——十日窗口的平方根法则只是近似，曲率与跳大时失真。分位数产出 VaR 与 ES；汇总用 <a href="/quant/expected-shortfall">Expected Shortfall</a>，理由是次可加性让分部之和不超过总账，VaR 做不到。回测逐日记穿透，Kupiec 的似然比检验与巴塞尔红黄绿区给出一阶判据。</p><p><span class="marginnote">数字实例：十日 VaR 常用一日 VaR 乘 √10≈3.16 近似。这一步假定日损益独立同分布：若日内有趋势或波动聚集，真实十日尾部可以明显超过 3.16 倍。平方根法则是便利近似，不是守恒定律。</span></p><p><span class="marginnote">巴塞尔回测交通灯以 \\(250\\) 个交易日、\\(99\\%\\) VaR 为口径：例外 \\(0\\)–\\(4\\) 次 绿区、\\(5\\)–\\(9\\) 次黄区、\\(10\\) 次及以上红区；黄区须解释，红区可触发乘数上调。例外本身不是坏消息，没有归因的例外才是。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么分环：只有切开，错误才能定位与归因。三种 VaR 算法在同一线性近正态账簿上应当接近，在期权、跳与体制切换上分叉——分叉是诊断信号，指出哪一环的假设被打破。条件波动进入情景，等价于让计量的松紧跟着市场状态走：同一分位数在波动放大时自动收紧。ES 的次可加性把「分部合规、总体超标」的悖论从制度里删掉。回测闭环是体系的免疫系统：例外先归因——是市场真极端、映射漏了因子、还是波动模型滞后——再决定动窗口、动模型还是动限额；跳过归因直接加乘数，等于把免疫系统改成疤痕组织。</p>',6)),(e(),r(l,null,{default:E(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%7B%22%E5%9B%9E%E6%B5%8B%E5%87%BA%E7%8E%B0%E4%BE%8B%E5%A4%96%22%7D%20--%3E%20A%7B%22%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%B8%82%E5%9C%BA%E7%9C%9F%E7%9A%84%E6%9E%81%E7%AB%AF%E5%90%97%EF%BC%9F%22%7D%0A%20%20A%20--%20%22%E6%98%AF%22%20--%3E%20B%5B%22%E6%A8%A1%E5%9E%8B%E6%AD%A3%E7%A1%AE%EF%BC%8C%E4%BE%8B%E5%A4%96%E5%9C%A8%E9%A2%84%E6%9C%9F%E9%A2%91%E7%8E%87%E5%86%85%EF%BC%8C%E8%AE%B0%E5%BD%95%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20A%20--%20%22%E6%98%A0%E5%B0%84%E6%BC%8F%E4%BA%86%E5%9B%A0%E5%AD%90%22%20--%3E%20C%5B%22%E8%A1%A5%E5%9B%A0%E5%AD%90%E5%B9%B6%E5%A3%B0%E6%98%8E%E5%9F%BA%E7%A1%80%E9%A3%8E%E9%99%A9%22%5D%0A%20%20A%20--%20%22%E6%B3%A2%E5%8A%A8%E6%A8%A1%E5%9E%8B%E6%BB%9E%E5%90%8E%22%20--%3E%20D%5B%22%E6%94%B9%E6%9D%A1%E4%BB%B6%E6%B3%A2%E5%8A%A8%E6%9B%B4%E6%96%B0%22%5D%0A%20%20C%20--%3E%20F%5B%22%E5%86%8D%E5%86%B3%E5%AE%9A%EF%BC%9A%E5%8A%A8%E7%AA%97%E5%8F%A3%E3%80%81%E5%8A%A8%E6%A8%A1%E5%9E%8B%E6%88%96%E5%8A%A8%E9%99%90%E9%A2%9D%22%5D%0A%20%20D%20--%3E%20F%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写分位数的定义与三种算法的取舍，那是 <a href="/quant/var-methods">VaR：历史、参数、MC</a> 的职责。中间价口径的计量不含变现成本，价差与冲击交给下一课的流动性计量；对手方与操作风险的损失生成机制独立，不能塞进市场因子。平方根法则不是定理，「从未违反」也不是模型正确的证明——\\(250\\) 天样本对 \\(99\\%\\) 分位几乎没有拒绝力。窗口外的联合尾部要靠压力测试与极值理论补，那是本课程后半段的事。</p><p><span class="marginnote">常见误区：把「回测从未违反」当模型正确的证明。99% 分位下 250 天平均只该出两三次例外，这么小的样本对「模型是否恰好对」几乎没有拒绝力——没报警不等于没病，这正是压力测试必须并存的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>市场风险体系是一条可分环归因的流水线，不是单个模型；故障按环定位。</li><li>因子映射要显式声明基础风险；双套数字的差值是隐性头寸的藏身处。</li><li>条件波动让分位数随 \\(\\sigma_t\\) 收紧；ES 的次可加性保证分部可加总。</li><li>回测例外的价值在归因闭环，不在次数本身。</li><li>出处：Jorion, <em>Value at Risk</em>；McNeil, Frey and Embrechts, <em>Quantitative Risk Management</em>, 2005；Kupiec, <em>Journal of Derivatives</em>, 1995 与巴塞尔市场风险回测框架；计量定义见本站 VaR 与 Expected Shortfall 两课。</li></ul>',5))])}const f=n(d,[["render",m]]);export{C as __pageData,f as default};
